{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "BalanceSheet",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "document_type", "company", "currency",
    "assets", "liabilities", "equity",
    "total_liabilities_and_equity", "financial_ratios"
  ],
  "properties": {
    "document_type": { "type": ["string", "null"] },
    "currency": { "type": ["string", "null"] },
    "company": {
      "type": "object", "additionalProperties": false,
      "required": ["name", "entity_code", "period_end", "period_months", "prepared_by"],
      "properties": {
        "name":           { "type": ["string", "null"] },
        "entity_code":    { "type": ["string", "null"] },
        "period_end":     { "type": ["string", "null"], "format": "date" },
        "period_months":  { "type": ["integer", "null"] },
        "prepared_by":    { "type": ["string", "null"] }
      }
    },
    "assets": {
      "type": "object", "additionalProperties": false,
      "required": ["current_assets", "fixed_assets", "other_assets", "total_assets"],
      "properties": {
        "current_assets": {
          "type": "object", "additionalProperties": false,
          "required": ["cash_and_bank_balance", "total_cash_and_bank_balance", "inventory", "prepaid_and_accounts_receivable", "total_prepaid_and_accounts_receivable", "other_current_assets", "total_current_assets"],
          "properties": {
            "cash_and_bank_balance":                  { "type": ["number", "null"] },
            "total_cash_and_bank_balance":            { "type": ["number", "null"] },
            "inventory":                              { "type": ["number", "null"] },
            "prepaid_and_accounts_receivable":        { "type": ["number", "null"] },
            "total_prepaid_and_accounts_receivable":  { "type": ["number", "null"] },
            "other_current_assets":                   { "type": ["number", "null"] },
            "total_current_assets":                   { "type": ["number", "null"] }
          }
        },
        "fixed_assets": {
          "type": "object", "additionalProperties": false,
          "required": ["machinery_and_equipment", "computer", "vehicle", "accumulated_depreciation", "total_fixed_assets"],
          "properties": {
            "machinery_and_equipment":  { "type": ["number", "null"] },
            "computer":                 { "type": ["number", "null"] },
            "vehicle":                  { "type": ["number", "null"] },
            "accumulated_depreciation": { "type": ["number", "null"] },
            "total_fixed_assets":       { "type": ["number", "null"] }
          }
        },
        "other_assets": {
          "type": "object", "additionalProperties": false,
          "required": ["start_up_costs", "franchise_fees", "accum_amort_startup_costs", "accum_amort_franchise_fees", "total_other_assets"],
          "properties": {
            "start_up_costs":             { "type": ["number", "null"] },
            "franchise_fees":             { "type": ["number", "null"] },
            "accum_amort_startup_costs":  { "type": ["number", "null"] },
            "accum_amort_franchise_fees": { "type": ["number", "null"] },
            "total_other_assets":         { "type": ["number", "null"] }
          }
        },
        "total_assets": { "type": ["number", "null"] }
      }
    },
    "liabilities": {
      "type": "object", "additionalProperties": false,
      "required": ["current_liabilities", "long_term_liabilities", "total_liabilities"],
      "properties": {
        "current_liabilities": {
          "type": "object", "additionalProperties": false,
          "required": ["redacted_liability", "sales_tax_payable", "deferred_income", "redacted_liability_2", "total_current_liabilities"],
          "properties": {
            "redacted_liability":       { "type": ["number", "null"] },
            "sales_tax_payable":        { "type": ["number", "null"] },
            "deferred_income":          { "type": ["number", "null"] },
            "redacted_liability_2":     { "type": ["number", "null"] },
            "total_current_liabilities":{ "type": ["number", "null"] }
          }
        },
        "long_term_liabilities": {
          "type": "object", "additionalProperties": false,
          "required": ["notes_payable_owner", "total_long_term_liabilities"],
          "properties": {
            "notes_payable_owner":          { "type": ["number", "null"] },
            "total_long_term_liabilities":  { "type": ["number", "null"] }
          }
        },
        "total_liabilities": { "type": ["number", "null"] }
      }
    },
    "equity": {
      "type": "object", "additionalProperties": false,
      "required": ["owners_equity", "owner_distributions", "total_stock_and_paid_in_capital", "retained_earnings", "net_income", "total_equity"],
      "properties": {
        "owners_equity":                  { "type": ["number", "null"] },
        "owner_distributions":            { "type": ["number", "null"] },
        "total_stock_and_paid_in_capital":{ "type": ["number", "null"] },
        "retained_earnings":              { "type": ["number", "null"] },
        "net_income":                     { "type": ["number", "null"] },
        "total_equity":                   { "type": ["number", "null"] }
      }
    },
    "total_liabilities_and_equity": { "type": ["number", "null"] },
    "financial_ratios": {
      "type": "object", "additionalProperties": false,
      "required": ["current_ratio", "debt_to_equity_ratio"],
      "properties": {
        "current_ratio":        { "type": ["number", "null"] },
        "debt_to_equity_ratio": { "type": ["number", "null"] }
      }
    }
  }
}

